import { CommonModule } from '@angular/common';
import { NgModule } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterModule, Routes } from '@angular/router';
import { IonicModule } from '@ionic/angular';
import { TranslateModule } from '@ngx-translate/core';
import { UtilsModule } from '@rsApp/modules/utils/utils.module';
import { UserServiceModule } from '../account-v2/providers/user.service';
import { AboutPageComponent } from './pages/about/about';
import { CoffeeClubPageComponent } from './pages/coffee-club/coffee-club';
import { ContactPageComponent } from './pages/contact/contact';
import { GuestSurveyPageComponent } from './pages/guest-survey/guest-survey';
import { LegalPageComponent } from './pages/legal/legal';
import { LogPageComponent } from './pages/log/log.page';
import { MessageCenterPageComponent } from './pages/message-center/message-center';
import { MorePageComponent } from './pages/more/more';
import { DynamicMenu } from './providers/dynamic-menu.service';
import { HeaderComponentModule } from '../header/header.component.module';

const routes: Routes = [
  {
    path: '',
    component: MorePageComponent,
  },
  { path: 'store', loadChildren: () => import('../store/store.module').then((m) => m.StoreModule) },
  {
    path: 'guest-survey',
    component: GuestSurveyPageComponent,
  },
  {
    path: 'about',
    component: AboutPageComponent,
    data: {
      hideTab: true,
    },
  },
  {
    path: 'contact',
    component: ContactPageComponent,
  },
  {
    path: 'legal',
    component: LegalPageComponent,
  },
  {
    path: 'log',
    component: LogPageComponent,
  },
  {
    path: 'coffee-club',
    component: CoffeeClubPageComponent,
  },
  {
    path: 'message-center',
    component: MessageCenterPageComponent,
  },
];

@NgModule({
  imports: [
    RouterModule.forChild(routes),
    CommonModule,
    FormsModule,
    TranslateModule,
    IonicModule,
    UtilsModule,
    UserServiceModule,
    HeaderComponentModule,
  ],
  declarations: [
    MorePageComponent,
    GuestSurveyPageComponent,
    AboutPageComponent,
    ContactPageComponent,
    LegalPageComponent,
    LogPageComponent,
    CoffeeClubPageComponent,
    MessageCenterPageComponent,
  ],
  providers: [DynamicMenu],
})
export class MoreModule {}
