import { Component, OnDestroy } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ENV } from '@app/env';
import { Capacitor } from '@capacitor/core';
import { AlertController, NavController, Platform } from '@ionic/angular';
import { Storage } from '@ionic/storage';
import { User } from '@rsApp/modules/account-v2/providers/user.service';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { IMenu } from '@rsApp/modules/interfaces/menu.interface';
import { IStore, ISystemService } from '@rsApp/modules/interfaces/store.interface';
import { CurrentStore } from '@rsApp/modules/store/providers/current-store.service';
import { StoreService } from '@rsApp/modules/store/providers/store.service';
import { LOCAL_LOCALE_KEY } from '@rsApp/modules/utils/constants/constants';
import { enumDisplayModeCustomService } from '@rsApp/modules/utils/enum/enum';
import { IPages } from '@rsApp/modules/utils/models/app-settings.model';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { GoogleAnalyticTracker } from '@rsApp/modules/utils/providers/google-tracker.service';
import { RSTracker } from '@rsApp/modules/utils/providers/rs-tracker.service';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import _ from 'lodash';
import { firstValueFrom, Subscription } from 'rxjs';
import { take } from 'rxjs/operators';
import { DynamicMenu } from '../../providers/dynamic-menu.service';

@Component({
  selector: 'page-more',
  templateUrl: 'more.html',
  styleUrls: ['more.scss'],
})
export class MorePageComponent implements OnDestroy {
  public user;
  public store: IStore;
  public isTeamMember = false;
  public customServices = ENV;
  public dynamicNavs = [];
  public links: IPages;
  public currentOnlineStore: IStore;
  public allServices: ISystemService[];
  public dynamicMenus: IMenu[];
  public menuCode = '';
  public locale: string;
  public title = 'More ...';
  subscriptions: Subscription[] = [];

  constructor(
    public auth: AuthService,
    public route: ActivatedRoute,
    public router: Router,
    public utils: Utils,
    public cache: CacheService,
    public cStore: CurrentStore,
    public userS: User,
    public platform: Platform,
    public alertCtrl: AlertController,
    public navCtrl: NavController,
    private storage: Storage,
    public tracker: RSTracker,
    public appSetting: AppSettings,
    public oStore: StoreService,
    public dynamicMenuSvc: DynamicMenu,
    private googleTracking: GoogleAnalyticTracker,
    public tenantSettingsStore: TenantSettingsStore
  ) {}

  async ionViewWillEnter() {
    const tenantSettingsStore = await this.tenantSettingsStore.getTenantSettings();
    this.links = tenantSettingsStore.pages;
  }

  async ionViewDidEnter() {
    this.menuCode = this.route.snapshot.paramMap.get('menu') || 'APP_MORE_MENU';
    this.locale = await this.storage.get(LOCAL_LOCALE_KEY);
    this.loadData();
  }

  ngOnDestroy() {
    this.subscriptions.forEach((s) => {
      s.unsubscribe();
    });
  }

  public async loadData() {
    this.store = await this.cStore.getStore();
    const getCUser = this.auth.getCurrentUser().subscribe(async (user) => {
      this.user = user;
      // verybad code
      const store = await this.cache.getItem('selected-store').catch();
      if (store) {
        await this.setCurrenStore(store);
      }
      // end very bad code
      if (this.user && !this.user.Segments) {
        const cardInfo = <any>await this.userS.getCardInfo(user.SRCardID).toPromise();
        this.user.Segments = (cardInfo && cardInfo.Segments) || null;
      }
      // Load check segment
      if (this.user && this.user.Segments && this.user.Segments.length > 0) {
        this.isTeamMember =
          _.find(this.user.Segments, function (o) {
            return o.SegmentId === 60;
          }) !== null;
      }

      // end Load check segment
      this.importForAfterDisplay();
    });
    this.subscriptions.push(getCUser);
  }
  public async importForAfterDisplay() {
    this.getOnlineStore();
    await this.getAllCustomServices();
    this.loadDynamicMenu();
  }
  public changeStore() {
    const cri = {
      keyword: this.store && this.store.ZipCode,
      size: 3,
    };
    this.cache.saveItem('store-search-params', cri);
    this.cache.saveItem('store-back', { route: ['/tabs/more'], key: 'selected-store' }, 'store');
    this.router.navigate([
      '/tabs/more/store/near',
      {
        type: 'chooseStore',
        returnRoute: 'tabs/more',
      },
    ]);
  }
  public goStore() {
    this.navCtrl.navigateRoot(['/store/find'], { animated: true, animationDirection: 'forward' });
  }
  public async setCurrenStore(store) {
    await firstValueFrom(this.userS.setStore(this.user, store));
    await this.cStore.setStore(store);
    this.cache.removeItem('selected-store');
    this.auth.refreshUser();
    // this.store = await this.cStore.getStore();
    this.store = store;
  }

  public async logOut() {
    await this.utils.showLoading();
    await this.auth.logout();
    this.store = null;
    await this.utils.hideLoading();
    this.navCtrl.navigateRoot(['/tabs/home']);
  }

  public async logInSignUp() {
    await this.utils.showLoading();
    this.navCtrl.navigateRoot(['/sign-in']).then(() => {
      this.utils.hideLoading();
    });
  }
  public goPharmacy() {
    if (!this.platform.is('cordova')) {
      return;
    }
    const urlScheme = ENV.PharmacyAppUrl;
    let appLink;

    if (this.platform.is('ios')) {
      appLink = ENV.AppStorePharmacyAppUrl;
    }
    if (this.platform.is('android')) {
      appLink = ENV.GooglePlayPharmacyAppUrl;
    }

    if (Capacitor.isNativePlatform()) {
      this.utils.openInSystem(appLink);
    } else {
      this.utils.openInSystem(urlScheme);
    }
  }
  async getOnlineStore() {
    // always fetch new store data from menu
    if (!this.currentOnlineStore && this.store) {
      this.currentOnlineStore = await firstValueFrom(this.oStore.getStoreByCode(this.store.StoreCode));
    }
    return this.currentOnlineStore;
  }
  async getAllCustomServices() {
    if (!this.allServices) {
      this.allServices = await firstValueFrom(this.oStore.getStoreSystemServices());
    }
    return this.allServices;
  }
  async checkCustomServiceAvailableInstore(serviceSlug?: string) {
    if (!this.store) {
      this.goStore();
      return;
    }
    let foundService;
    try {
      const services = await this.getAllCustomServices();
      foundService = _.find(services, { UrlSlug: String((foundService && foundService.UrlSlug) || serviceSlug) });
    } catch (error) {
      console.error(error);
      return;
    }

    if (foundService?.Type === 'CustomService') {
      try {
        await this.getOnlineStore();
      } catch (error) {
        console.error(error);
      }
    }

    if (!foundService) {
      this.goToCollectionPage(null, serviceSlug);
    } else {
      this.goToCollectionPage(foundService);
    }
  }
  goToCollectionPage(service?: ISystemService, serviceSlug?: string) {
    if (service) {
      this.storage.set('CurrentService', JSON.stringify(service));
    }
    try {
      const systemService = _.find(
        this.allServices,
        (s) => s.ServiceId === (service ? service.ParentId || service.ServiceId : serviceSlug)
      );
      if (!systemService) {
        console.error('systemService not found');
        return;
      }
      const contentType = systemService.ServiceName.toLowerCase().replace(' ', '-');
      this.eventTrackSelectContent(contentType, '');
      if ((service && service.DisplayMode === enumDisplayModeCustomService.Products) || serviceSlug === 'gift-cards') {
        this.router.navigate([`/commerce/${systemService.UrlSlug}/list-products/${service.UrlSlug}`]);
      } else if (service && service.Type === 'CustomService') {
        this.router.navigate([`/commerce/${systemService.UrlSlug}/collections/${service.UrlSlug}`]);
      } else {
        // is System Service
        this.router.navigate([
          `/commerce/${service && service.Type === 'CustomService' ? systemService.UrlSlug : service.UrlSlug}/`,
        ]);
      }
    } catch (error) {
      console.error('Error navigating to collection page:', error);
    }
  }
  loadDynamicNavigationServiceSetting() {
    this.appSetting
      .getDynamicNavigationServiceSetting()
      .pipe(take(1))
      .subscribe((dynamicNavs) => {
        this.dynamicNavs = dynamicNavs;
      });
  }

  eventTrackSelectContent(contentType, contentId) {
    this.googleTracking.gtagTrackSelectContent(contentType, contentId);
  }

  async loadDynamicMenu() {
    await this.utils.showLoading();
    const s = this.dynamicMenuSvc
      .getMenu(this.menuCode, this.user, this.store, 'Mobile', this.locale)
      .subscribe(async (moreMenu) => {
        if (
          !moreMenu ||
          moreMenu.IsDeleted ||
          !moreMenu.Childs ||
          (!this.user && moreMenu.Options && moreMenu.Options.AuthRequired)
        ) {
          return;
        }
        const dynamicMenus: IMenu[] = _.filter(moreMenu.Childs, (menu) => {
          const isValid = (!this.user && !menu.Options.AuthRequired) || this.user;
          return isValid;
        });
        this.title = moreMenu.Label;

        this.dynamicMenus = dynamicMenus.filter((menu) => {
          if (!menu.Options.ServiceId) return true;

          const dataService = this.allServices.find((service) => service.ServiceId === menu.Options.ServiceId);
          return dataService && dataService.IsActive;
        });
        await this.utils.hideLoading();
      });
    this.subscriptions.push(s);
  }

  onClickDynamicMenu(menu: IMenu) {
    const mobileUrl = menu.UrlLink;
    if (mobileUrl) {
      if (mobileUrl.indexOf('func://') > -1) {
        const startIdxParams = mobileUrl.indexOf('(') + 1;
        const endIdxParams = mobileUrl.indexOf(')');
        const fnName = (mobileUrl.slice(0, startIdxParams - 1) + mobileUrl.slice(endIdxParams + 1)).replace(
          'func://',
          ''
        );
        const params = mobileUrl.slice(startIdxParams, endIdxParams);
        const fn = this[fnName];
        if (fn && typeof fn === 'function') {
          fn.call(this, params);
        }
        return;
      }
    }
    this.utils.navigateByUrl(mobileUrl);
  }

  public getPageName() {
    return 'MorePage';
  }
}
