import { Component, ViewEncapsulation } from '@angular/core';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'page-guest-survey',
  templateUrl: 'guest-survey.html',
  styleUrls: ['guest-survey.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class GuestSurveyPageComponent {
  surveyStore: any;

  constructor(
    public utils: Utils,
    public route: ActivatedRoute,
    public router: Router
  ) {}

  goSurvey() {
    switch (this.surveyStore) {
      case 'treetSide':
        this.utils.openInaAppBrowser('https://albertsons.az1.qualtrics.com/jfe/form/SV_6WEsX4eEQbIGu4R?Banner=united');
        break;
      case 'united':
        this.utils.openInaAppBrowser('https://albertsons.az1.qualtrics.com/jfe/form/SV_6WEsX4eEQbIGu4R?Banner=united');
        break;
      case 'mktstreet':
        this.utils.openInaAppBrowser('https://albertsons.az1.qualtrics.com/jfe/form/SV_6WEsX4eEQbIGu4R?Banner=united');
        break;
      case 'albertsons':
        this.utils.openInaAppBrowser('https://albertsons.az1.qualtrics.com/jfe/form/SV_6WEsX4eEQbIGu4R?Banner=united');
        break;
      case 'amigos':
        this.utils.openInaAppBrowser('https://albertsons.az1.qualtrics.com/jfe/form/SV_6WEsX4eEQbIGu4R?Banner=united');
        break;
      case 'unitedExpress':
        this.utils.openInaAppBrowser('https://albertsons.az1.qualtrics.com/jfe/form/SV_6WEsX4eEQbIGu4R?Banner=united');
        break;

      default:
        break;
    }
  }
  public getPageName() {
    return 'GuestSurveyPage';
  }
}
