import { Component, ViewEncapsulation } from '@angular/core';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { Router } from '@angular/router';

@Component({
  selector: 'coffee-club-page',
  templateUrl: 'coffee-club.html',
  styleUrls: ['coffee-club.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class CoffeeClubPageComponent {
  coffeeClubComponent = '';

  constructor(
    public utils: Utils,
    public cre: Credential,
    public router: Router
  ) {}

  ionViewWillEnter() {
    this.loadData();
  }

  loadData() {
    this.coffeeClubComponent = `<united-coffee-club></united-coffee-club>`;
  }
  public getPageName() {
    return 'CoffeeClubPage';
  }
}
