import { Component } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'message-center',
  templateUrl: './message-center.html',
  styleUrls: ['./message-center.scss'],
})
export class MessageCenterPageComponent {
  constructor(public router: Router) {}

  public notificationHtml = '';

  async ionViewWillEnter() {
    if (this.notificationHtml) {
      this.notificationHtml = '';
    }

    customElements.whenDefined('dxp-notification-page').then(() => {
      this.notificationHtml = '<dxp-notification-page></dxp-notification-page>';
    });
  }
}
