import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { IPages } from '@rsApp/modules/utils/models/app-settings.model';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { Utils } from '@rsApp/modules/utils/providers/utils';

@Component({
  selector: 'page-legal',
  templateUrl: 'legal.html',
  styleUrls: ['legal.scss'],
})
export class LegalPageComponent {
  links: IPages;

  constructor(
    public route: ActivatedRoute,
    public router: Router,
    public utils: Utils,
    public tenantSettingsStore: TenantSettingsStore
  ) {}

  async ionViewWillEnter() {
    const tenantSetting = await this.tenantSettingsStore.getTenantSettings();
    this.links = tenantSetting.pages;
  }
  public getPageName() {
    return 'LegalPage';
  }
}
